import { createElement } from 'react'
import type { ResumeData } from '../validators/resume'
import {
  getFontStack,
  getFontSizes,
  getCustomFontSizes,
  getGoogleFontUrl,
  DEFAULT_HEADING_SIZE,
  DEFAULT_BODY_SIZE,
} from '../config/fontConfig'
import { getTemplate } from '../components/templates'
// Pre-compiled, minified Tailwind bundle scoped to the resume templates.
// Generated by `node scripts/build-resume-css.js` (runs automatically via
// package.json prebuild/predev/pretest hooks). Imported as a JSON module so
// Next.js's bundler ships it with the serverless function on every target
// (Vercel, Docker, self-hosted) — no fs.readFile or origin fetching needed.
import resumePdfCss from '../styles/resume-pdf-css.json'

// ─── SSR: render the real React template used by the preview ─────────────────
// The preview in ResumePreview.tsx applies a wrapperStyle with CSS vars
// (--r-title/--r-body/--r-section/--r-meta) and a font-family. We replicate
// that wrapper here so the SSR output matches the preview pixel-for-pixel.

// Next.js App Router refuses static ESM imports of `react-dom/server` inside
// any module that might be bundled outside a server-only context. Loading it
// via `require` at call time keeps this module portable (API routes,
// background jobs, tests) without triggering the webpack guard.
function renderTemplateToMarkup(
  data: ResumeData,
  templateId: string,
): string {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const reactDomServer = require('react-dom/server') as typeof import('react-dom/server')
  const Template = getTemplate(templateId)
  return reactDomServer.renderToStaticMarkup(createElement(Template, { data }))
}

export function renderResumeHTML(data: ResumeData, templateId: string): string {
  const templateMarkup = renderTemplateToMarkup(data, templateId)

  const fontFamily = data.styling?.fontFamily
  const hasCustomSizes =
    data.styling?.headingSize != null || data.styling?.bodySize != null
  const sizes = hasCustomSizes
    ? getCustomFontSizes(
        data.styling?.headingSize ?? DEFAULT_HEADING_SIZE,
        data.styling?.bodySize ?? DEFAULT_BODY_SIZE,
      )
    : getFontSizes(data.styling?.fontSize)
  const googleFontUrl = getGoogleFontUrl(fontFamily)
  const googleFontLink = googleFontUrl
    ? `<link rel="stylesheet" href="${googleFontUrl}">`
    : ''
  const fontStack = getFontStack(fontFamily)

  // A4 @ 72dpi = 595 × 842 px. Matches PAGE_WIDTH/PAGE_HEIGHT in ResumePreview.
  return `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  ${googleFontLink}
  <style>${resumePdfCss.css}</style>
  <style>
    @page { size: A4; margin: 0; }
    html, body {
      margin: 0;
      padding: 0;
      background: #ffffff;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
    #resume-pages-root {
      width: 595px;
      background: #ffffff;
    }
    .resume-wrapper {
      font-family: ${fontStack};
      --r-title: ${sizes.title};
      --r-body: ${sizes.body};
      --r-section: ${sizes.section};
      --r-meta: ${sizes.meta};
    }
    #resume-measure-root {
      position: absolute;
      visibility: hidden;
      pointer-events: none;
      width: 547px;
    }
    .resume-page {
      width: 595px;
      height: 842px;
      background: #fff;
      box-sizing: border-box;
      overflow: hidden;
      page-break-after: always;
    }
    .resume-page-inner {
      padding: 24px;
      box-sizing: border-box;
    }
    .resume-page-viewport {
      width: 547px;
      height: 794px;
      overflow: hidden;
      position: relative;
    }
    .resume-continuation-header {
      position: absolute;
      top: 0;
      z-index: 10;
    }
    .resume-page-content {
      width: 547px;
    }
  </style>
</head>
<body>
  <div id="resume-measure-root" class="resume-wrapper">
    <div id="resume-template-root">${templateMarkup}</div>
  </div>
  <div id="resume-pages-root"></div>
  <script>
    (function paginateForPdf() {
      const PAGE_HEIGHT = 842;
      const PAGE_PADDING = 24;
      const CONTENT_HEIGHT = PAGE_HEIGHT - PAGE_PADDING * 2;

      function relativeTop(el, root) {
        const rootRect = root.getBoundingClientRect();
        return Math.round(el.getBoundingClientRect().top - rootRect.top);
      }

      function bottom(unit) {
        return unit.offsetTop + unit.offsetHeight;
      }

      function fits(bottomPx, pageStart, pageHeight) {
        return bottomPx <= pageStart + pageHeight;
      }

      function pushBreak(breaks, continuation, at, needsHeader) {
        if (breaks[breaks.length - 1] === at) return;
        breaks.push(at);
        continuation.push(needsHeader);
      }

      function measureSections(templateRoot) {
        const marked = Array.from(templateRoot.querySelectorAll('[data-resume-section]'));
        const hasNonSkillsMarker = marked.some(el => el.getAttribute('data-resume-section') !== 'skills');

        const measureSkills = (skillsEl) => {
          const skillsTop = relativeTop(skillsEl, templateRoot);
          const headerEl = skillsEl.querySelector('[data-resume-skills-header]');
          const categoryEls = Array.from(skillsEl.querySelectorAll('[data-resume-skills-category]'));
          return {
            kind: 'skills',
            offsetTop: skillsTop,
            offsetHeight: skillsEl.offsetHeight,
            header: headerEl ? {
              offsetTop: relativeTop(headerEl, templateRoot) - skillsTop,
              offsetHeight: headerEl.offsetHeight,
            } : { offsetTop: 0, offsetHeight: 0 },
            categories: categoryEls.map((el, index) => ({
              categoryIndex: index,
              offsetTop: relativeTop(el, templateRoot) - skillsTop,
              offsetHeight: el.offsetHeight,
            })),
          };
        };

        const measureBlock = (el) => ({
          kind: 'block',
          offsetTop: relativeTop(el, templateRoot),
          offsetHeight: el.offsetHeight,
        });

        if (marked.length > 0 && hasNonSkillsMarker) {
          return marked
            .sort((a, b) => relativeTop(a, templateRoot) - relativeTop(b, templateRoot))
            .map(el => el.getAttribute('data-resume-section') === 'skills' ? measureSkills(el) : measureBlock(el));
        }

        return Array.from(templateRoot.children).map(child => {
          const skillsEl =
            child.getAttribute('data-resume-section') === 'skills'
              ? child
              : child.querySelector('[data-resume-section="skills"]');
          return skillsEl ? measureSkills(skillsEl) : measureBlock(child);
        });
      }

      function computePlan(sections, pageHeight) {
        const breaks = [0];
        const continuation = [false];

        let pageStart = 0;
        for (const section of sections) {
          if (section.kind === 'block') {
            const blockBottom = bottom(section);
            if (fits(blockBottom, pageStart, pageHeight)) continue;
            if (section.offsetHeight > pageHeight) {
              if (section.offsetTop > pageStart) {
                pushBreak(breaks, continuation, section.offsetTop, false);
                pageStart = section.offsetTop;
              }
              let next = pageStart + pageHeight;
              while (next < blockBottom) {
                pushBreak(breaks, continuation, next, false);
                pageStart = next;
                next += pageHeight;
              }
            } else {
              pushBreak(breaks, continuation, section.offsetTop, false);
              pageStart = section.offsetTop;
            }
            continue;
          }

          const skillsTop = section.offsetTop;
          const skillsBottom = bottom(section);
          if (section.categories.length === 0) {
            if (!fits(skillsBottom, pageStart, pageHeight)) {
              pushBreak(breaks, continuation, skillsTop, false);
              pageStart = skillsTop;
            }
            continue;
          }

          if (fits(skillsBottom, pageStart, pageHeight)) continue;

          const firstCategoryBottom = skillsTop + bottom(section.categories[0]);
          const firstChunkBottom = Math.max(
            firstCategoryBottom,
            skillsTop + bottom(section.header) + section.categories[0].offsetHeight
          );

          if (!fits(firstChunkBottom, pageStart, pageHeight) && skillsTop > pageStart) {
            pushBreak(breaks, continuation, skillsTop, false);
            pageStart = skillsTop;
          }

          // Match preview planner: if the whole section now fits on the fresh page,
          // do not force per-category continuation breaks.
          if (fits(skillsBottom, pageStart, pageHeight)) continue;

          for (let i = 0; i < section.categories.length; i++) {
            const category = section.categories[i];
            const categoryBreakTop = skillsTop + category.offsetTop;
            const categoryBottomAbs = skillsTop + bottom(category);
            const maxCategoryHeightWithHeader = pageHeight - section.header.offsetHeight;

            if (i === 0) {
              // Match preview planner: keep first category on current page only if it fits.
              if (!fits(categoryBottomAbs, pageStart, pageHeight) && categoryBreakTop > pageStart) {
                pushBreak(breaks, continuation, categoryBreakTop, false);
                pageStart = categoryBreakTop;
              }
            } else {
              pushBreak(breaks, continuation, categoryBreakTop, true);
              pageStart = categoryBreakTop;
            }

            // Prevent clipping when one category is taller than a single page
            // (minus duplicated section header on continuation pages).
            if (category.offsetHeight > maxCategoryHeightWithHeader) {
              let next = pageStart + pageHeight;
              while (next < categoryBottomAbs) {
                pushBreak(breaks, continuation, next, true);
                pageStart = next;
                next += pageHeight;
              }
            }
          }
        }

        return { breaks, continuation };
      }

      const measureRoot = document.getElementById('resume-measure-root');
      const templateRoot = document.getElementById('resume-template-root');
      const pagesRoot = document.getElementById('resume-pages-root');
      if (!measureRoot || !templateRoot || !pagesRoot) {
        window.__resumePagesReady = true;
        return;
      }

      const sections = measureSections(templateRoot);
      const plan = computePlan(sections, CONTENT_HEIGHT);
      const templateHTML = templateRoot.outerHTML;
      const headerEl = templateRoot.querySelector('[data-resume-skills-header]');
      const rootRect = templateRoot.getBoundingClientRect();
      const headerRect = headerEl ? headerEl.getBoundingClientRect() : null;
      const headerMetrics = {
        left: headerRect ? Math.max(0, Math.round(headerRect.left - rootRect.left)) : 0,
        width: headerRect ? Math.max(0, Math.round(headerRect.width)) : 547,
        height: headerEl ? headerEl.offsetHeight : 0,
        html: headerEl ? headerEl.innerHTML : '<h2>Skills</h2>',
      };

      pagesRoot.innerHTML = '';
      plan.breaks.forEach((breakTop, pageIndex) => {
        const page = document.createElement('div');
        page.className = 'resume-page';
        const inner = document.createElement('div');
        inner.className = 'resume-page-inner';
        const viewport = document.createElement('div');
        viewport.className = 'resume-page-viewport';

        if (plan.continuation[pageIndex]) {
          const header = document.createElement('div');
          header.className = 'resume-continuation-header';
          header.style.left = headerMetrics.left + 'px';
          header.style.width = headerMetrics.width + 'px';
          header.style.height = headerMetrics.height + 'px';
          header.innerHTML = headerMetrics.html;
          viewport.appendChild(header);
        }

        const content = document.createElement('div');
        content.className = 'resume-wrapper resume-page-content';
        content.style.marginTop = (-breakTop + (plan.continuation[pageIndex] ? headerMetrics.height : 0)) + 'px';
        content.innerHTML = templateHTML;

        viewport.appendChild(content);
        inner.appendChild(viewport);
        page.appendChild(inner);
        pagesRoot.appendChild(page);
      });

      measureRoot.remove();
      window.__resumePagesReady = true;
    })();
  </script>
</body>
</html>`
}

// ─── Puppeteer renderer ──────────────────────────────────────────────────────

interface RenderPdfOptions {
  margin?: { top: string; right: string; bottom: string; left: string }
}

async function renderPdfFromHtml(
  html: string,
  options?: RenderPdfOptions,
): Promise<Buffer> {
  // Dynamic require to handle environments without Puppeteer.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const puppeteer = require('puppeteer-core')

  // @sparticuz/chromium v110+ extracts a brotli-compressed Chromium at runtime.
  // For this to work on Vercel/Lambda, the package must be in
  // next.config.js → experimental.serverComponentsExternalPackages so webpack
  // leaves the archive intact. We also MUST pass chromium.args (the ~22 flags
  // tuned for serverless single-process execution); passing only --no-sandbox
  // causes the browser to crash or fail to spawn.
  let launchArgs: string[] = ['--no-sandbox', '--disable-setuid-sandbox']
  let executablePath: string

  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const chromiumMod = require('@sparticuz/chromium')
    const chromium = chromiumMod.default ?? chromiumMod
    if (Array.isArray(chromium.args) && chromium.args.length > 0) {
      launchArgs = [
        ...chromium.args,
        '--hide-scrollbars',
        '--disable-web-security',
      ]
    }
    executablePath = await chromium.executablePath()
  } catch {
    executablePath =
      process.env.CHROMIUM_PATH || '/usr/bin/chromium-browser'
  }

  const browser = await puppeteer.launch({
    args: launchArgs,
    executablePath,
    headless: true,
  })

  try {
    const page = await browser.newPage()
    // Match puppeteer's A4 CSS-pixel dimensions (8.27in × 11.69in @ 96dpi).
    // This ensures the browser's layout engine sees the same viewport that
    // the subsequent page.pdf({ format: 'A4' }) call will use.
    await page.setViewport({ width: 794, height: 1123 })
    await page.setContent(html, { waitUntil: 'networkidle0' })
    await page.waitForFunction(() => (window as { __resumePagesReady?: boolean }).__resumePagesReady === true)

    // ── Compute the exact scale to match the preview's page count ───────────
    //
    // The editor preview designs every page at 595×842 CSS px (A4 at 72dpi)
    // and decides page breaks based on that. Puppeteer's PDF output uses
    // 96dpi, where A4 = 794×1123 CSS px. The "naive" width-filling scale is
    // 794/595 = 1.3345, but at that scale, a resume that exactly fills one
    // preview page (842 px source height) scales to 1123.65 px — 0.65 px
    // over A4, which forces one orphan line onto a second page.
    //
    // Fix: measure the actual rendered element height, figure out how many
    // A4 pages the preview would have shown for that height (1 page per
    // 842 px source), then pick the largest scale that (a) still fills the
    // A4 width as much as possible and (b) never exceeds `pages × 1123 px`
    // after scaling. This snaps the PDF page count to the preview's exactly.
    const SOURCE_WIDTH = 595
    const SOURCE_PAGE_HEIGHT = 842
    const A4_WIDTH = 794
    const A4_HEIGHT = 1123

    const naturalHeight: number = await page.evaluate(() => {
      const el = document.getElementById('resume-pages-root') as HTMLElement | null
      return el ? el.offsetHeight : 842
    })

    const pagesIntended = Math.max(
      1,
      Math.ceil(naturalHeight / SOURCE_PAGE_HEIGHT),
    )
    const widthScale = A4_WIDTH / SOURCE_WIDTH
    const heightScale = (pagesIntended * A4_HEIGHT) / naturalHeight
    // Clamp to puppeteer's valid scale range (0.1, 2).
    const scale = Math.max(0.1, Math.min(2, Math.min(widthScale, heightScale)))

    const pdfBuffer = await page.pdf({
      format: 'A4',
      printBackground: true,
      scale,
      // Zero puppeteer margins — the #resume-page element encodes its own
      // 24px padding that matches the preview's PAGE_PADDING.
      margin: options?.margin ?? {
        top: '0',
        right: '0',
        bottom: '0',
        left: '0',
      },
    })
    return Buffer.from(pdfBuffer)
  } finally {
    await browser.close()
  }
}

// ─── Public API ──────────────────────────────────────────────────────────────

export async function generatePDF(
  data: ResumeData,
  templateId: string,
): Promise<Buffer> {
  const html = renderResumeHTML(data, templateId)
  return renderPdfFromHtml(html)
}

/** @deprecated — kept for backward compatibility. Prefer `renderResumeHTML`. */
export function generateResumeHTML(data: ResumeData, templateId: string): string {
  return renderResumeHTML(data, templateId)
}
